import { styled } from '@linaria/react'
import React, { FC, HTMLAttributes, ReactNode } from 'react'
import cx from 'classnames'
import classNames from 'classnames'
import { useTheme, ThemeProp } from '@utils/'

export type LinkProps = HTMLAttributes<HTMLElement> & {
  className?: string | object
  to?: string
  external?: boolean
  disabled?: boolean
  children?: ReactNode
}

export const Link: FC<LinkProps> = ({
  children,
  disabled,
  className,
  external,
  to,
  ...props
}: LinkProps): JSX.Element => {
  const { theme } = useTheme()

  const additionalProps = external ? { target: '_blank', rel: 'noopener noreferrer' } : null

  return (
    <StyledLink {...additionalProps} {...props} theme={theme} href={to} className={cx(classNames, { disabled })}>
      {children}
    </StyledLink>
  )
}

const StyledLink = styled.a<LinkProps & ThemeProp>`
  text-decoration: none;
  color: ${(props) => props.theme.colors.accent};
  font-size: ${(props) => props.theme.typography.sizes.m};

  &:hover {
  }

  &:focus {
    border-bottom: 1px dashed transparent;
  }

  &.disabled {
    opacity: 0.4;
    cursor: default;
    pointer-events: none;
  }
`
