import React, { FC } from 'react'
import { defaultThemeConfig, ThemeOptions, ThemeConfig, ThemeMode } from '@utils/constants'

export type ThemeContextProps = {
  theme: ThemeConfig | ThemeOptions
  mode: ThemeMode
  setMode: (theme: ThemeMode) => void
}

export const ThemeContext = React.createContext<ThemeContextProps>({
  theme: defaultThemeConfig,
  mode: ThemeMode.Light,
  setMode: (_: ThemeMode) => {}
})

export type ThemeProviderProps = {
  children: React.ReactNode
  theme?: ThemeConfig
  mode?: ThemeMode
}

export const ThemeProvider: FC<ThemeProviderProps> = ({
  children,
  theme: themeConfig = defaultThemeConfig,
  mode: themeMode = ThemeMode.Light
}: ThemeProviderProps) => {
  const [mode, setMode] = React.useState(themeMode)

  const theme = {
    ...themeConfig,
    colors: new Proxy(themeConfig.colors, {
      get(target, prop, receiver): string {
        const property: string = prop as string
        const themeOptions: ThemeOptions = target[mode] as ThemeOptions

        if (themeOptions[property]) {
          return themeOptions[property]
        }

        return Reflect.get(target, property, receiver)
      }
    })
  }

  return <ThemeContext.Provider value={{ theme, mode, setMode }}>{children}</ThemeContext.Provider>
}
