import { GridBreakPoint, GridConfig } from '@utils/types'
import { mergeLiteralArgs } from '@utils/helpers'

export const VARIABLE_PREFIX = 'ui-'

export const uiPrefix = (strings: TemplateStringsArray, ...args: any[]): string => {
  return '--' + VARIABLE_PREFIX + mergeLiteralArgs(strings, args)
}

