import { GridBreakPoint, GridConfig } from "../types"

export type MediaQueryHelpers = {breakPointUp: (b: GridBreakPoint, s: string) => string, breakPointDown: (b: GridBreakPoint, s: string) => string}

export const getMediaQueryHelpers = (gridConfig: GridConfig): MediaQueryHelpers => {
    return {
        breakPointUp: (breakPoint: GridBreakPoint, styles: string): string => {
            const width = gridConfig.breakPoints[breakPoint]
            if(breakPoint && width) {
                return `@media screen and (min-width: ${width}px) {${styles}}`
            }
        
            return styles
        },
        breakPointDown: (breakPoint: GridBreakPoint, styles: string): string => {
            const width = gridConfig.breakPoints[breakPoint]
            if(breakPoint && width) {
                return `@media screen and (max-width: ${width - 0.02}px) {${styles}}`
            }
        
            return styles
        }
    }
}